def _rebuild_from_artifact(arch: str, path: str, kind: str) -> nn.Module:
    """Load a saved converted artifact into a runnable model."""
    if kind in ("int8_dynamic", "int8_static"):
        payload = torch.load(path, map_location="cpu", weights_only=False)
        st = payload["state"]
        if "pickled" in st:
            m = torch.load(io.BytesIO(st["pickled"]), map_location="cpu",
                           weights_only=False)
            m.eval()
            return m
        # CNN static: re-convert a fresh parent, then load the saved state.
        # The parent weights are recovered from the re-conversion's fp32
        # parent (the saved state_dict carries only the quantized params).
        # We re-run the frozen conversion from the same seed-0 parent.
        from .evaln import load_checkpoint
        parent, _ = load_checkpoint(arch, 0)
        m = _convert_static(parent, arch)
        m.load_state_dict(st["state_dict"])
        m.eval()
        return m
    payload = torch.load(path, map_location="cpu", weights_only=False)
