def _artifact_state(model: nn.Module, kind: str, arch: str) -> dict:
    if kind == "int4_simulated":
        flat = {}
        for name, m_ in model.named_modules():
            if isinstance(m_, (Int4PackedLinear, Int4PackedConv)):
                for k, v in m_.state_dict().items():
                    flat[f"{name}.{k}"] = v
        # Also save the fp32 parent weights so the reload can rebuild the
        # base model with the correct shapes before wrapping.
        fp32 = {}
        for name, m_ in model.named_modules():
            if not isinstance(m_, (Int4PackedLinear, Int4PackedConv)):
                for k, v in m_.state_dict().items():
                    if torch.is_tensor(v) and v.is_floating_point():
                        fp32[f"{name}.{k}"] = v
        return {"packed": flat, "fp32": fp32}
    if kind in ("fp16", "bf16"):
        return {k: v for k, v in model.state_dict().items()}
    # int8: pickle the whole model (handles quantized modules + FX GraphModules).
    # CNN static (fused ConvReLU2d) does not pickle (qnnpack packed params break
    # FX GraphModule re-tracing on unpickle). The FX conversion is deterministic
    # (two fresh converts from the same parent + calib give maxdiff 0.0), so the
    # CNN static artifact stores a marker and the reload path re-converts.
    if kind == "int8_static" and arch == "cnn":
        return {"reconvert": True}
    buf = io.BytesIO()
    torch.save(model, buf)
    return {"pickled": buf.getvalue()}


def _rebuild_from_artifact(arch: str, path: str, kind: str) -> nn.Module:
    """Load a saved converted artifact into a runnable model."""
    if kind in ("int8_dynamic", "int8_static"):
        payload = torch.load(path, map_location="cpu", weights_only=False)
        st = payload["state"]
        if "reconvert" in st and st["reconvert"]:
            # CNN static: the FX-fused ConvReLU2d cannot be pickled on this
            # build (qnnpack packed params break GraphModule re-tracing on
            # unpickle). The conversion is deterministic, so re-convert from
            # the same parent + frozen calibration inputs.
            from .evaln import load_checkpoint
            parent, _ = load_checkpoint(arch, 0)
            m = _convert_static(parent, arch)
            m.eval()
            return m
        m = torch.load(io.BytesIO(st["pickled"]), map_location="cpu",
                       weights_only=False)

